    }
}
"}

{"path": "/tmp/sv-593e72796369488a82c94884b688381c/Components/Board/BoardColumn.razor", "file_text": "<div class="board-column">
    <div class="column-header">
        <h3>@Title <span class="column-count">(@Tasks.Count)</span></h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      IsMoving="movingTaskId == task.Id"
                      OnMoveLeft="HandleMoveLeft"
                      OnMoveRight="HandleMoveRight" />
        }
    </div>
    <div class="column-footer">
        <AddTaskForm Status="@Status"
                     TaskService="TaskService"
                     OnTaskCreated="OnTaskCreated" />
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = [];
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<(int TaskId, string Direction)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }
    [Parameter, EditorRequired] public ITaskService TaskService { get; set; } = default!;

    private int? movingTaskId;

    private async Task HandleMoveLeft(int taskId)
    {
        movingTaskId = taskId;
        await OnMoveTask.InvokeAsync((taskId, "left"));
        movingTaskId = null;
    }

    private async Task HandleMoveRight(int taskId)
    {
        movingTaskId = taskId;
        await OnMoveTask.InvokeAsync((taskId, "right"));
        movingTaskId = null;
    }
}
"}

