@page "/board"
@using sv_593e72796369488a82c94884b688381c.Components.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (isLoading)
{
    <p class="board-loading">Loading tasks…</p>
}
else if (errorMessage is not null)
{
    <div class="board-error">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardSummaryBar Total="allTasks.Count"
                     TodoCount="TodoTasks.Count"
                     InProgressCount="InProgressTasks.Count"
                     DoneCount="DoneTasks.Count"
                     OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="board-columns">
        <BoardColumn Title="To Do" Status="To Do"
                     Tasks="FilteredTodo"
                     ShowMoveLeft="false" ShowMoveRight="true"
                     OnMoveTask="HandleMoveTask"
                     OnTaskCreated="HandleTaskCreated"
                     TaskService="TaskService" />

        <BoardColumn Title="In Progress" Status="In Progress"
                     Tasks="FilteredInProgress"
                     ShowMoveLeft="true" ShowMoveRight="true"
                     OnMoveTask="HandleMoveTask"
                     OnTaskCreated="HandleTaskCreated"
                     TaskService="TaskService" />

        <BoardColumn Title="Done" Status="Done"
                     Tasks="FilteredDone"
                     ShowMoveLeft="true" ShowMoveRight="false"
                     OnMoveTask="HandleMoveTask"
                     OnTaskCreated="HandleTaskCreated"
                     TaskService="TaskService" />
    </div>
}

@code {
    private List<TaskItem> allTasks = [];
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = ["To Do", "In Progress", "Done"];

    private List<TaskItem> TodoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => allTasks.Where(t => t.Status == "Done").ToList();

    private List<TaskItem> FilteredTodo => ApplySearch(TodoTasks);
    private List<TaskItem> FilteredInProgress => ApplySearch(InProgressTasks);
    private List<TaskItem> FilteredDone => ApplySearch(DoneTasks);

    private List<TaskItem> ApplySearch(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;
        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task HandleMoveTask((int TaskId, string Direction) move)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == move.TaskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Statuses, task.Status);
        var newIndex = move.Direction == "left" ? currentIndex - 1 : currentIndex + 1;

        if (newIndex < 0 || newIndex >= Statuses.Length) return;

        var newStatus = Statuses[newIndex];

        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            // Replace the task with updated status
            allTasks = allTasks.Select(t => t.Id == task.Id ? t with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void HandleTaskCreated(TaskItem newTask)
    {
        allTasks.Add(newTask);
    }
}

.board-loading,
.board-error {
    text-align: center;
    padding: 2rem;
}

.board-error button {
    margin-top: 0.5rem;
    padding: 0.4rem 1rem;
    cursor: pointer;
}

/* Summary Bar */
.board-summary {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.summary-stat {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 70px;
}

.stat-value {
    font-size: 1.5rem;
    font-weight: 700;
}

.stat-label {
    font-size: 0.8rem;
    color: #6c757d;
}

.stat-overdue .stat-value {
    color: #dc3545;
}

/* Search */
.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

/* Columns */
.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 0.75rem;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.column-header h3 {
    margin: 0 0 0.5rem;
    font-size: 1rem;
}

.column-count {
    color: #6c757d;
    font-weight: 400;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 60px;
}

.column-footer {
    margin-top: 0.75rem;
}

/* Task Card */
.task-card {
    background: #fff;
    border-radius: 6px;
    padding: 0.75rem;
    border-left: 4px solid #ced4da;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
}

.task-priority-high {
    border-left-color: #dc3545;
}

.task-priority-medium {
    border-left-color: #ffc107;
}

.task-priority-low {
    border-left-color: #28a745;
}

.task-title {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.4rem;
    font-size: 0.8rem;
    color: #6c757d;
}

.task-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.4rem;
}

.priority-badge {
    font-size: 0.7rem;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
    font-weight: 600;
    text-transform: uppercase;
}

.priority-high {
    background: #dc3545;
    color: #fff;
}

.priority-medium {
    background: #ffc107;
    color: #212529;
}

.priority-low {
    background: #28a745;
    color: #fff;
}

.task-due {
    font-size: 0.8rem;
    color: #6c757d;
}

.task-actions {
    display: flex;
    gap: 0.4rem;
}

.btn-move {
    flex: 1;
    padding: 0.25rem 0.4rem;
    font-size: 0.75rem;
    border: 1px solid #ced4da;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
}

.btn-move:hover:not(:disabled) {
    background: #e9ecef;
}

.btn-move:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Add Task */
.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 2px dashed #ced4da;
    background: transparent;
    border-radius: 6px;
    cursor: pointer;
    color: #6c757d;
    font-size: 0.85rem;
}

.btn-add-task:hover {
    border-color: #6c757d;
    color: #212529;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    background: #fff;
    padding: 0.75rem;
    border-radius: 6px;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.85rem;
}

.form-actions {
    display: flex;
    gap: 0.4rem;
}

.btn-save,
.btn-cancel {
    flex: 1;
    padding: 0.35rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-save {
    background: #0d6efd;
    color: #fff;
}

.btn-save:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-cancel {
    background: #e9ecef;
}

.btn-cancel:hover:not(:disabled) {
    background: #dee2e6;
}

.form-error {
    color: #dc3545;
    font-size: 0.8rem;
    margin: 0;
}

